                                                "type": "TextBlock",
                                                "weight": "Bolder"
                                            },
                                            {
                                                "size": "Small",
                                                "style": "Person",
                                                "type": "Image",
                                                "url": "https://avatars2.githubusercontent.com/u/4855743?s=280&v=4"
                                            }
