{
        "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
        "contentVersion": "1.0.0.0",
        "metadata": {
            "title": "Create-IBMResilientIncident", 
            "description": "This playbook will create an IBM Resilient incident from an Azure Sentinel incident. It will also add the Azure Sentinel Incident Entities as IBM Resilient Incident Artifacts.",
            "prerequisites": ["This playbook uses a custom connector in Logic Apps (deployed as part of this template). The template is set to not need a gateway, but if IBM Resilient is on-prem you can deploy a Logic Apps gateway and set the connector to use that gateway. You will need to update the connector and delete/re-add the API connection."],
            "lastUpdateTime": "2021-05-30T10:00:00.000Z", 
            "entities": [], 
            "tags": ["Sync"], 
            "support": {
                "tier": "Community" 
            },
            "author": {
                "name": "Nicholas DiCola"
            }
        },
        "parameters": {
            "PlaybookName": {
                "defaultValue": "Create-IBMResilientIncident",
                "type": "string"
            },
            "IBMResilientServerName": {
                "type": "string"
            },
            "IBMResilientOrgNumber": {
                "type": "string"
            }
        },
        "variables": {
            "AzureSentinelConnectionName": "[concat('azuresentinel-', parameters('PlaybookName'))]",
            "IBMReslientConnectionName": "[concat('ibmresilient-', parameters('PlaybookName'))]"
        },
        "resources": [
            {
                "type": "Microsoft.Resources/deployments",
                "apiVersion": "2020-10-01",
                "name": "linkedTemplate",
                "properties": {
                    "mode": "Incremental",
                    "templateLink": {
                        "uri": "https://raw.githubusercontent.com/Azure/Azure-Sentinel/master/Playbooks/Create-IBMResilientIncident/customConnector/azuredeploy.json",
                        "contentVersion": "1.0.0.0"
                    },
                    "parameters": {
                        "IBMResilientServerName": {
                            "value": "[parameters('IBMResilientServerName')]"
                        },
                        "IBMResilientOrgNumber": {
                            "value": "[parameters('IBMResilientOrgNumber')]"
                        }
                    }
                }
            },
            {
                "type": "Microsoft.Web/connections",
                "apiVersion": "2016-06-01",
                "name": "[variables('IBMReslientConnectionName')]",
                "location": "[resourceGroup().location]",
                "dependsOn": [
                    "[resourceId('Microsoft.Resources/deployments', 'linkedTemplate')]"
                ],
                "properties": {
                    "displayName": "IBM_Resilient",
                    "customParameterValues": {},
                    "api": {
                        "id": "[concat('/subscriptions/', subscription().subscriptionId, '/resourceGroups/', resourceGroup().name, '/providers/Microsoft.Web/customApis/Resilient-Incidents')]"                   
                    }
                }
            },
            {
                "type": "Microsoft.Web/connections",
                "apiVersion": "2016-06-01",
                "name": "[variables('AzureSentinelConnectionName')]",
                "location": "[resourceGroup().location]",
                "kind": "V1",
                "properties": {
                    "displayName": "[parameters('PlaybookName')]",
                    "customParameterValues": {},
                    "parameterValueType": "Alternative",
                    "api": {
                        "id": "[concat('/subscriptions/', subscription().subscriptionId, '/providers/Microsoft.Web/locations/', resourceGroup().location, '/managedApis/azuresentinel')]"
                    }
                }
            },
            {
                "type": "Microsoft.Logic/workflows",
                "apiVersion": "2017-07-01",
                "name": "[parameters('PlaybookName')]",
                "location": "[resourceGroup().location]",
                "tags": {
                "LogicAppsCategory": "security",
                "hidden-SentinelTemplateName": "Create-IBMResilientIncident",
                "hidden-SentinelTemplateVersion": "1.0"
            },
                "identity": {
                    "type": "SystemAssigned"
                },
                "dependsOn": [
                    "[resourceId('Microsoft.Web/connections', variables('AzureSentinelConnectionName'))]",
                    "[resourceId('Microsoft.Web/connections', variables('IBMReslientConnectionName'))]",
                    "[resourceId('Microsoft.Resources/deployments', 'linkedTemplate')]"
                ],
                "properties": {
                    "state": "Enabled",
                    "definition": {
                        "$schema": "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#",
                        "actions": {
                            "Entities_-_Get_Accounts": {
                                "inputs": {
                                    "body": "@triggerBody()?['object']?['properties']?['relatedEntities']",
                                    "host": {
                                        "connection": {
                                            "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                        }
                                    },
                                    "method": "post",
                                    "path": "/entities/account"
                                },
                                "runAfter": {
                                    "GetTimeInEpoch": [
                                        "Succeeded"
                                    ]
                                },
                                "type": "ApiConnection"
                            },
                            "Entities_-_Get_Hosts": {
                                "inputs": {
                                    "body": "@triggerBody()?['object']?['properties']?['relatedEntities']",
                                    "host": {
                                        "connection": {
                                            "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                        }
                                    },
                                    "method": "post",
                                    "path": "/entities/host"
                                },
                                "runAfter": {
                                    "Entities_-_Get_Accounts": [
                                        "Succeeded"
                                    ]
                                },
                                "type": "ApiConnection"
                            },
                            "Entities_-_Get_IPs": {
                                "inputs": {
                                    "body": "@triggerBody()?['object']?['properties']?['relatedEntities']",
                                    "host": {
                                        "connection": {
                                            "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                        }
                                    },
                                    "method": "post",
                                    "path": "/entities/ip"
                                },
                                "runAfter": {
                                    "Entities_-_Get_Hosts": [
                                        "Succeeded"
                                    ]
                                },
                                "type": "ApiConnection"
                            },
                            "For_each": {
                                "actions": {
                                    "Switch_2": {
                                        "cases": {
                                            "Case": {
                                                "actions": {
                                                    "create_IncidentArtifact": {
                                                        "inputs": {
                                                            "body": {
                                                                "description": {
                                                                    "content": "From Azure Sentinel",
                                                                    "format": "text"
                                                                },
                                                                "ip": {
                                                                    "destination": false,
                                                                    "source": false
                                                                },
                                                                "type": {
                                                                    "name": "IP Address"
                                                                },
                                                                "value": "@items('For_each')?['Address']"
                                                            },
                                                            "host": {
                                                                "connection": {
                                                                    "name": "@parameters('$connections')['Resilient-Incidents']['connectionId']"
                                                                }
                                                            },
                                                            "method": "post",
                                                            "path": "/incidents/@{encodeURIComponent(body('create_incident')?['id'])}/artifacts"
                                                        },
                                                        "runAfter": {},
                                                        "type": "ApiConnection"
                                                    }
                                                },
                                                "case": "ip"
                                            },
                                            "Case_2": {
                                                "actions": {
                                                    "create_IncidentArtifact_2": {
                                                        "inputs": {
                                                            "body": {
                                                                "description": {
                                                                    "content": "From Azure Sentinel - AAD GUID: @{items('For_each')?['AadUserId']}",
                                                                    "format": "text"
                                                                },
                                                                "ip": {
                                                                    "destination": false,
                                                                    "source": false
                                                                },
                                                                "type": {
                                                                    "name": "User Account"
                                                                },
                                                                "value": "@{concat(items('For_each')?['Name'], '@', items('For_each')?['UPNSuffix'])}"
                                                            },
                                                            "host": {
                                                                "connection": {
                                                                    "name": "@parameters('$connections')['Resilient-Incidents']['connectionId']"
                                                                }
                                                            },
                                                            "method": "post",
                                                            "path": "/incidents/@{encodeURIComponent(body('create_incident')?['id'])}/artifacts"
                                                        },
                                                        "runAfter": {},
                                                        "type": "ApiConnection"
                                                    }
                                                },
                                                "case": "account"
                                            },
                                            "Case_3": {
                                                "actions": {
                                                    "create_IncidentArtifact_3": {
                                                        "inputs": {
                                                            "body": {
                                                                "description": {
                                                                    "content": "From Azure Sentinel - AzureID: @{items('For_each')?['AzureID']}",
                                                                    "format": "text"
                                                                },
                                                                "ip": {
                                                                    "destination": false,
                                                                    "source": false
                                                                },
                                                                "type": {
                                                                    "name": "System Name"
                                                                },
                                                                "value": "@items('For_each')?['HostName']"
                                                            },
                                                            "host": {
                                                                "connection": {
                                                                    "name": "@parameters('$connections')['Resilient-Incidents']['connectionId']"
                                                                }
                                                            },
                                                            "method": "post",
                                                            "path": "/incidents/@{encodeURIComponent(body('create_incident')?['id'])}/artifacts"
                                                        },
                                                        "runAfter": {},
                                                        "type": "ApiConnection"
                                                    }
                                                },
                                                "case": "host"
                                            },
                                            "Case_4": {
                                                "actions": {
                                                    "create_IncidentArtifact_4": {
                                                        "inputs": {
                                                            "body": {
                                                                "description": {
                                                                    "content": "From Azure Sentinel",
                                                                    "format": "text"
                                                                },
                                                                "ip": {
                                                                    "destination": false,
                                                                    "source": false
                                                                },
                                                                "type": {
                                                                    "name": "URL"
                                                                },
                                                                "value": "@items('For_each')?['Url']"
                                                            },
                                                            "host": {
                                                                "connection": {
                                                                    "name": "@parameters('$connections')['Resilient-Incidents']['connectionId']"
                                                                }
                                                            },
                                                            "method": "post",
                                                            "path": "/incidents/@{encodeURIComponent(body('create_incident')?['id'])}/artifacts"
                                                        },
                                                        "runAfter": {},
                                                        "type": "ApiConnection"
                                                    }
                                                },
                                                "case": "url"
                                            }
                                        },
                                        "default": {
                                            "actions": {}
                                        },
                                        "expression": "@items('For_each')['Type']",
                                        "runAfter": {},
                                        "type": "Switch"
                                    }
                                },
                                "foreach": "@body('Parse_JSON')",
                                "runAfter": {
                                    "Parse_JSON": [
                                        "Succeeded"
                                    ]
                                },
                                "type": "Foreach"
                            },
                            "GetIncidentTimeInEpoch": {
                                "inputs": "@div(sub(ticks(triggerBody()?['object']?['properties']?['createdTimeUtc']), ticks('1970-01-01T00:00:00Z')), 10000)",
                                "runAfter": {
                                    "Entities_-_Get_IPs": [
                                        "Succeeded"
                                    ]
                                },
                                "type": "Compose"
                            },
                            "GetTimeInEpoch": {
                                "inputs": "@div(sub(ticks(utcNow()), ticks('1970-01-01T00:00:00Z')), 10000)",
                                "runAfter": {
                                    "Initialize_variable": [
                                        "Succeeded"
                                    ]
                                },
                                "type": "Compose"
                            },
                            "Initialize_variable": {
                                "inputs": {
                                    "variables": [
                                        {
                                            "name": "ReslientVariable",
                                            "type": "string",
                                            "value": "null"
                                        }
                                    ]
                                },
                                "runAfter": {},
                                "type": "InitializeVariable"
                            },
                            "Parse_JSON": {
                                "inputs": {
                                    "content": "@triggerBody()?['object']?['properties']?['relatedEntities']",
                                    "schema": {
                                        "items": {
                                            "properties": {
                                                "$id": {
                                                    "type": "string"
                                                },
                                                "AadUserId": {
                                                    "type": "string"
                                                },
                                                "Address": {
                                                    "type": "string"
                                                },
                                                "AppId": {
                                                    "type": "integer"
                                                },
                                                "AzureID": {
                                                    "type": "string"
                                                },
                                                "HostName": {
                                                    "type": "string"
                                                },
                                                "InstanceName": {
                                                    "type": "string"
                                                },
                                                "Name": {
                                                    "type": "string"
                                                },
                                                "OMSAgentID": {
                                                    "type": "string"
                                                },
                                                "Type": {
                                                    "type": "string"
                                                },
                                                "UPNSuffix": {
                                                    "type": "string"
                                                },
                                                "Url": {
                                                    "type": "string"
                                                }
                                            },
                                            "required": [
                                                "$id",
                                                "Type"
                                            ],
                                            "type": "object"
                                        },
                                        "type": "array"
                                    }
                                },
                                "runAfter": {
                                    "create_incident": [
                                        "Succeeded"
                                    ]
                                },
                                "type": "ParseJson"
                            },
                            "Switch": {
                                "cases": {
                                    "Case": {
                                        "actions": {
                                            "Set_variable_2": {
                                                "inputs": {
                                                    "name": "ReslientVariable",
                                                    "value": "High"
                                                },
                                                "runAfter": {},
                                                "type": "SetVariable"
                                            }
                                        },
                                        "case": "High"
                                    },
                                    "Case_2": {
                                        "actions": {
                                            "Set_variable_3": {
                                                "inputs": {
                                                    "name": "ReslientVariable",
                                                    "value": "Medium"
                                                },
                                                "runAfter": {},
                                                "type": "SetVariable"
                                            }
                                        },
                                        "case": "Medium"
                                    },
                                    "Case_3": {
                                        "actions": {
                                            "Set_variable_4": {
                                                "inputs": {
                                                    "name": "ReslientVariable",
                                                    "value": "Low"
                                                },
                                                "runAfter": {},
                                                "type": "SetVariable"
                                            }
                                        },
                                        "case": "Low"
                                    },
                                    "Case_4": {
                                        "actions": {
                                            "Set_variable_5": {
                                                "inputs": {
                                                    "name": "ReslientVariable",
                                                    "value": "No Risk"
                                                },
                                                "runAfter": {},
                                                "type": "SetVariable"
                                            }
                                        },
                                        "case": "Informational"
                                    }
                                },
                                "default": {
                                    "actions": {
                                        "Set_variable": {
                                            "inputs": {
                                                "name": "ReslientVariable",
                                                "value": "Informational"
                                            },
                                            "runAfter": {},
                                            "type": "SetVariable"
                                        }
                                    }
                                },
                                "expression": "@triggerBody()?['object']?['properties']?['severity']",
                                "runAfter": {
                                    "GetIncidentTimeInEpoch": [
                                        "Succeeded"
                                    ]
                                },
                                "type": "Switch"
                            },
                            "create_incident": {
                                "inputs": {
                                    "body": {
                                        "description": "@triggerBody()?['object']?['properties']?['description']",
                                        "discovered_date": "@outputs('GetIncidentTimeInEpoch')",
                                        "name": "AS: @{triggerBody()?['object']?['properties']?['incidentNumber']}- @{triggerBody()?['object']?['properties']?['title']}",
                                        "severity_code": {
                                            "name": "@variables('ReslientVariable')"
                                        }
                                    },
                                    "host": {
                                        "connection": {
                                            "name": "@parameters('$connections')['Resilient-Incidents']['connectionId']"
                                        }
                                    },
                                    "method": "post",
                                    "path": "/incidents"
                                },
                                "runAfter": {
                                    "Switch": [
                                        "Succeeded"
                                    ]
                                },
                                "type": "ApiConnection"
                            }
                        },
                        "contentVersion": "1.0.0.0",
                        "outputs": {},
                        "parameters": {
                            "$connections": {
                                "defaultValue": {},
                                "type": "Object"
                            }
                        },
                        "triggers": {
                            "Microsoft_Sentinel_incident": {
                                "inputs": {
                                    "body": {
                                        "callback_url": "@{listCallbackUrl()}"
                                    },
                                    "host": {
                                        "connection": {
                                            "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                        }
                                    },
                                    "path": "/incident-creation"
                                },
                                "type": "ApiConnectionWebhook"
                            }
                        }
                    },
                    "parameters": {
                        "$connections": {
                            "value": {
                                "azuresentinel": {
                                    "connectionId": "[resourceId('Microsoft.Web/connections', variables('AzureSentinelConnectionName'))]",
                                    "connectionName": "[variables('AzureSentinelConnectionName')]",
                                    "id": "[concat('/subscriptions/', subscription().subscriptionId, '/providers/Microsoft.Web/locations/', resourceGroup().location, '/managedApis/azuresentinel')]",
                                    "connectionProperties": {
                                        "authentication": {
                                            "type": "ManagedServiceIdentity"
                                        }
                                    }
                                },
                                "Resilient-Incidents": {
                                    "connectionId": "[resourceId('Microsoft.Web/connections', variables('IBMReslientConnectionName'))]",
                                    "connectionName": "[variables('IBMReslientConnectionName')]",
                                   "id": "[concat('/subscriptions/', subscription().subscriptionId, '/resourceGroups/', resourceGroup().name, '/providers/Microsoft.Web/customApis/Resilient-Incidents')]"

                                }
                            }
                        }
                    }
                }
            }
        ]
    }

