{
    "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
    "contentVersion": "1.0.0.0",
    "metadata": {
        "title": "Block URL From Teams - Palo Alto Wildfire and PAN-OS",
        "description": "This playbook is used to add Malicious URL to security policy rules of PAN-OS VM on teams response",
        "mainSteps": [ "1. Fetches detailed verdict information of the URL.", "2. Checks for verdict status. If it is benign then it closes the incident with URL verdict information.", "3. If verdict status is other than benign (phishing, malware, grayware) then it creates the address object for URL and adds address object to the security policy rules." ],
        "prerequisites": [
            "1. Palo Alto WildFire Custom Connector and Palo Alto PAN-OS custom connector needs to be deployed prior to the deployment of this playbook under the same resource group.",
            "2. Generate Wildfire API key to establish the connection to wildfire custom connector.",
            "3. Security policy rule in the Palo Alto PAN-OS VM."
        ],
        "prerequisitesDeployTemplateFile": [ "../../WildfireConnector/azuredeploy.json" ],
        "lastUpdateTime": "2021-07-27T00:00:00.000Z",
        "entities": [ "URL" ],
        "tags": [ "Remediation", "Response from teams" ],
        "support": {
            "tier": "community"
        },
        "author": {
            "name": "Accenture"
        }
    },
    "parameters": {
        "PlaybookName": {
            "defaultValue": "Block-URL-From-Teams-PaloAltoWildFire",
            "type": "string",
            "metadata": {
                "description": "Enter Block URL From Teams Playbook Name"
            },
            "minLength": 3
        },
        "WildfireCustomConnectorName": {
            "defaultValue": "PaloAltoWildFire",
            "type": "String",
            "metadata": {
                "description": "Enter Palo Alto WildFire Custom Connector Name"
            },
            "minLength": 3
        },
        "PAN-OSCustomConnectorName": {
            "defaultValue": "PaloAltoPANOS",
            "type": "String",
            "metadata": {
                "description": "Enter Palo Alto PAN-OS Custom Connector Name"
            },
            "minLength": 3
        },
        "WildfireAPIKey": {
            "type": "securestring",
            "metadata": {
                "description": "Enter WildFire API Key"
            },
            "minLength": 3
        },
        "SecurityPolicyRule": {
            "type": "string",
            "metadata": {
                "description": "Enter Security Policy Rule Name - Created in PAN-OS"
            },
            "minLength": 3
        }
    },
    "variables": {
        "WildFireConnectionName": "[concat('WildFireConnector-', parameters('PlaybookName'))]",
        "PANOSConnectionName": "[concat('PANOSConnector-', parameters('PlaybookName'))]",
        "AzureSentinelConnectionName": "[concat('AzureSentinelConnector-', parameters('PlaybookName'))]",
        "TeamsConnectionName": "[concat('TeamsConnector-', parameters('PlaybookName'))]"
    },
    "resources": [
        {
            "type": "Microsoft.Web/connections",
            "apiVersion": "2016-06-01",
            "name": "[variables('WildFireConnectionName')]",
            "location": "[resourceGroup().location]",
            "properties": {
                "customParameterValues": {},
                "api": {
                    "id": "[concat('/subscriptions/', subscription().subscriptionId, '/resourceGroups/', resourceGroup().name, '/providers/Microsoft.Web/customApis/', parameters('WildfireCustomConnectorName'))]"
                }
            }
        },
        {
            "type": "Microsoft.Web/connections",
            "apiVersion": "2016-06-01",
            "name": "[variables('PANOSConnectionName')]",
            "location": "[resourceGroup().location]",
            "properties": {
                "customParameterValues": {},
                "api": {
                    "id": "[concat('/subscriptions/', subscription().subscriptionId, '/resourceGroups/', resourceGroup().name, '/providers/Microsoft.Web/customApis/', parameters('PAN-OSCustomConnectorName'))]"
                }
            }
        },
        {
            "type": "Microsoft.Web/connections",
            "apiVersion": "2016-06-01",
            "name": "[variables('AzureSentinelConnectionName')]",
            "location": "[resourceGroup().location]",
            "kind": "V1",
            "properties": {
                "displayName": "[variables('AzureSentinelConnectionName')]",
                "customParameterValues": {},
                "parameterValueType": "Alternative",
                "api": {
                    "id": "[concat('/subscriptions/', subscription().subscriptionId, '/providers/Microsoft.Web/locations/', resourceGroup().location, '/managedApis/azuresentinel')]"
                }
            }
        },
        {
            "type": "Microsoft.Web/connections",
            "apiVersion": "2016-06-01",
            "name": "[variables('TeamsConnectionName')]",
            "location": "[resourceGroup().location]",
            "properties": {
                "customParameterValues": {},
                "api": {
                    "id": "[concat('/subscriptions/', subscription().subscriptionId, '/providers/Microsoft.Web/locations/', resourceGroup().location, '/managedApis/teams')]"
                }
            }
        },
        {
            "type": "Microsoft.Logic/workflows",
            "apiVersion": "2017-07-01",
            "name": "[parameters('PlaybookName')]",
            "location": "[resourceGroup().location]",
            "dependsOn": [
                "[resourceId('Microsoft.Web/connections', variables('PANOSConnectionName'))]",
                "[resourceId('Microsoft.Web/connections', variables('WildFireConnectionName'))]",
                "[resourceId('Microsoft.Web/connections', variables('AzureSentinelConnectionName'))]",
                "[resourceId('Microsoft.Web/connections', variables('TeamsConnectionName'))]"
            ],
            "identity": {
                "type": "SystemAssigned"
            },
            "properties": {
                "state": "Enabled",
                "definition": {
                    "$schema": "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#",
                    "contentVersion": "1.0.0.0",
                    "parameters": {
                        "$connections": {
                            "defaultValue": {},
                            "type": "Object"
                        },
                        "APIKey": {
                            "defaultValue": "[parameters('WildfireAPIKey')]",
                            "type": "SecureString"
                        },
                        "SecurityPolicyRule": {
                            "defaultValue": "[parameters('SecurityPolicyRule')]",
                            "type": "String"
                        }
                    },
                    "triggers": {
                        "Microsoft_Sentinel_incident": {
                            "type": "ApiConnectionWebhook",
                            "inputs": {
                                "body": {
                                    "callback_url": "@{listCallbackUrl()}"
                                },
                                "host": {
                                    "connection": {
                                        "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                    }
                                },
                                "path": "/incident-creation"
                            }
                        }
                    },
                    "actions": {
                        "Add_icon_to_the_comments": {
                            "runAfter": {
                                "Post_an_adaptive_card_to_change_the_Incident_configuration": [
                                    "Succeeded"
                                ]
                            },
                            "type": "Compose",
                            "inputs": "<img src=\"https://avatars.githubusercontent.com/u/4855743?s=200&v=4\",alt=\"Lamp\" width=\"32\" height=\"32\" />",
                            "description": "Wildfire logo for incident comment"
                        },
                        "Append_consolidated_comment": {
                            "runAfter": {
                                "Check_for_malicious_verdict": [
                                    "Succeeded"
                                ]
                            },
                            "type": "AppendToArrayVariable",
                            "inputs": {
                                "name": "finalConsolidatedcomments",
                                "value": "@variables('incidentComment')"
                            },
                            "description": " consolidate comments of each iteration to update to incident"
                        },
                        "Check_for_malicious_verdict": {
                            "actions": {
                                "Append_incident_comment": {
                                    "runAfter": {
                                        "Create_HTML_table_for_verdict": [
                                            "Succeeded"
                                        ]
                                    },
                                    "type": "AppendToStringVariable",
                                    "inputs": {
                                        "name": "incidentComment",
                                        "value": "<b>Below list of URL(s) is/are associated with incident.</b>\n@{body('Create_HTML_table_for_verdict')}"
                                    },
                                    "description": "To append incident comment"
                                },
                                "Create_HTML_table_for_verdict": {
                                    "runAfter": {},
                                    "type": "Table",
                                    "inputs": {
                                        "columns": [
                                            {
                                                "header": "URL",
                                                "value": "@item()?['URL']"
                                            },
                                            {
                                                "header": "Verdict",
                                                "value": "@item()?['Wildfire_Verdict']"
                                            },
                                            {
                                                "header": "Security Policy Rule",
                                                "value": "@parameters('SecurityPolicyRule')"
                                            },
                                            {
                                                "header": "Action Taken",
                                                "value": "Blocked"
                                            }
                                        ],
                                        "format": "HTML",
                                        "from": "@variables('ConsoildatedverdictArray')"
                                    },
                                    "description": "To create html table for incident comment"
                                }
                            },
                            "runAfter": {
                                "For_each_URL": [
                                    "Succeeded"
                                ]
                            },
                            "expression": {
                                "and": [
                                    {
                                        "not": {
                                            "equals": [
                                                "@variables('ConsoildatedverdictArray')",
                                                "@null"
                                            ]
                                        }
                                    }
                                ]
                            },
                            "type": "If",
                            "description": "Condition to check if consolidated array has values"
                        },
                        "Check_if_user_changed_configuration": {
                            "actions": {
                                "Update_Incident_for_configuration_case": {
                                    "runAfter": {},
                                    "type": "ApiConnection",
                                    "inputs": {
                                        "body": {
                                            "classification": {
                                                "ClassificationAndReason": "@{body('Post_an_adaptive_card_to_change_the_Incident_configuration')['data']['incidentStatus']}"
                                            },
                                            "incidentArmId": "@triggerBody()?['object']?['id']",
                                            "severity": "@{body('Post_an_adaptive_card_to_change_the_Incident_configuration')['data']['incidentSeverity']}",
                                            "status": "Closed"
                                        },
                                        "host": {
                                            "connection": {
                                                "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                            }
                                        },
                                        "method": "put",
                                        "path": "/Incidents"
                                    }
                                }
                            },
                            "runAfter": {
                                "For_each_incident_comment": [
                                    "Succeeded"
                                ]
                            },
                            "expression": {
                                "and": [
                                    {
                                        "equals": [
                                            "@body('Post_an_adaptive_card_to_change_the_Incident_configuration')['submitActionId']",
                                            "Update configuration"
                                        ]
                                    }
                                ]
                            },
                            "type": "If",
                            "description": "Condition to check SOC action for configuration change"
                        },
                        "Construct_string_from_consolidated_verdict_array": {
                            "runAfter": {
                                "Append_consolidated_comment": [
                                    "Succeeded"
                                ]
                            },
                            "type": "Compose",
                            "inputs": "@replace(replace(replace(replace(replace(replace(replace(string(\r\nvariables('ConsoildatedverdictArray')),'[',''),']',''),'\"',''),'{',''),'},','                   '),'\"',''),'}','\r\n')",
                            "description": "consolidated array in string format"
                        },
                        "Entities_-_Get_URLs": {
                            "runAfter": {},
                            "type": "ApiConnection",
                            "inputs": {
                                "body": "@triggerBody()?['object']?['properties']?['relatedEntities']",
                                "host": {
                                    "connection": {
                                        "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                    }
                                },
                                "method": "post",
                                "path": "/entities/url"
                            }
                        },
                        "For_each_URL": {
                            "foreach": "@body('Entities_-_Get_URLs')?['URLs']",
                            "actions": {
                                "Check_if_URL_is_benign": {
                                    "actions": {
                                        "Add_incident_comment": {
                                            "runAfter": {
                                                "Create_HTML_table_for_benign_verdict": [
                                                    "Succeeded"
                                                ]
                                            },
                                            "type": "SetVariable",
                                            "inputs": {
                                                "name": "incidentComment",
                                                "value": "@body('Create_HTML_table_for_benign_verdict')"
                                            },
                                            "description": "To store incident comment"
                                        },
                                        "Create_HTML_table_for_benign_verdict": {
                                            "runAfter": {},
                                            "type": "Table",
                                            "inputs": {
                                                "columns": [
                                                    {
                                                        "header": "URL",
                                                        "value": "@body('Parse_verdict_JSON')?['get-verdict-info']?['url']"
                                                    },
                                                    {
                                                        "header": "Verdict",
                                                        "value": "Benign"
                                                    },
                                                    {
                                                        "header": "Analysis Time",
                                                        "value": "@body('Parse_verdict_JSON')?['get-verdict-info']?['analysis_time']"
                                                    },
                                                    {
                                                        "header": "Valid",
                                                        "value": "@body('Parse_verdict_JSON')?['get-verdict-info']?['valid']"
                                                    },
                                                    {
                                                        "header": "Comment",
                                                        "value": "The sample is safe and does not exhibit malicious behavior."
                                                    }
                                                ],
                                                "format": "HTML",
                                                "from": "@createArray(body('Parse_verdict_JSON'))"
                                            },
                                            "description": "To create html table for incident comment"
                                        }
                                    },
                                    "runAfter": {
                                        "Parse_verdict_JSON": [
                                            "Succeeded"
                                        ]
                                    },
                                    "else": {
                                        "actions": {
                                            "Append_destination_member": {
                                                "runAfter": {
                                                    "Switch_for_verdict_value": [
                                                        "Succeeded"
                                                    ]
                                                },
                                                "type": "SetVariable",
                                                "inputs": {
                                                    "name": "destinationMembers",
                                                    "value": "@body('Get_existing_member_of_the_security_rules')?['result']?['entry']?[0]?['destination']?['member']"
                                                },
                                                "description": "To append destination member"
                                            },
                                            "Check_If_address_object_exists": {
                                                "actions": {
                                                    "Check_if_security_rule_applied_to_URL": {
                                                        "actions": {
                                                            "Append_consolidated_verdict_": {
                                                                "runAfter": {
                                                                    "Append_verdict_object": [
                                                                        "Succeeded"
                                                                    ]
                                                                },
                                                                "type": "AppendToArrayVariable",
                                                                "inputs": {
                                                                    "name": "ConsoildatedverdictArray",
                                                                    "value": "@variables('VerdictObject')"
                                                                },
                                                                "description": "To append verdict object"
                                                            },
                                                            "Append_verdict_object": {
                                                                "runAfter": {},
                                                                "type": "SetVariable",
                                                                "inputs": {
                                                                    "name": "VerdictObject",
                                                                    "value": {
                                                                        "URL": "@{items('For_each_URL')?['Url']}",
                                                                        "Wildfire_Verdict": "@{variables('verdictDescription')}"
                                                                    }
                                                                },
                                                                "description": "For existing address object"
                                                            }
                                                        },
                                                        "runAfter": {
                                                            "Filter_security_policy_member": [
                                                                "Succeeded"
                                                            ]
                                                        },
                                                        "expression": {
                                                            "and": [
                                                                {
                                                                    "greater": [
                                                                        "@length(body('Filter_security_policy_member'))",
                                                                        0
                                                                    ]
                                                                }
                                                            ]
                                                        },
                                                        "type": "If",
                                                        "description": "Check if security rule applied to URL"
                                                    },
                                                    "Filter_security_policy_member": {
                                                        "runAfter": {},
                                                        "type": "Query",
                                                        "inputs": {
                                                            "from": "@body('Get_existing_member_of_the_security_rules')?['result']?['entry']",
                                                            "where": "@contains(item()?['destination']?['member'], items('For_each_URL')?['Url'])"
                                                        },
                                                        "description": "To filter security policy member based on URL"
                                                    }
                                                },
                                                "runAfter": {
                                                    "Filter_address_object": [
                                                        "Succeeded"
                                                    ]
                                                },
                                                "expression": {
                                                    "and": [
                                                        {
                                                            "greater": [
                                                                "@length(body('Filter_address_object'))",
                                                                0
                                                            ]
                                                        }
                                                    ]
                                                },
                                                "type": "If",
                                                "description": " Check address object exists for the URL "
                                            },
                                            "Check_if_the_URL_is_added_to_security_policy_rules": {
                                                "actions": {
                                                    "Check_action_on_adaptive_card": {
                                                        "actions": {
                                                            "Add_address_objects_to_security_policy_rules": {
                                                                "runAfter": {
                                                                    "Append_destination_member_for_new_URL": [
                                                                        "Succeeded"
                                                                    ]
                                                                },
                                                                "type": "ApiConnection",
                                                                "inputs": {
                                                                    "body": {
                                                                        "entry": {
                                                                            "@@name": "@parameters('SecurityPolicyRule')",
                                                                            "action": "allow",
                                                                            "application": {
                                                                                "member": "any"
                                                                            },
                                                                            "category": {
                                                                                "member": "any"
                                                                            },
                                                                            "destination": {
                                                                                "member": "@variables('destinationMembers')"
                                                                            },
                                                                            "from": {
                                                                                "member": "any"
                                                                            },
                                                                            "hip-profiles": {
                                                                                "member": "any"
                                                                            },
                                                                            "service": {
                                                                                "member": "any"
                                                                            },
                                                                            "source": {
                                                                                "member": "any"
                                                                            },
                                                                            "source-user": {
                                                                                "member": "any"
                                                                            },
                                                                            "to": {
                                                                                "member": "any"
                                                                            }
                                                                        }
                                                                    },
                                                                    "host": {
                                                                        "connection": {
                                                                            "name": "@parameters('$connections')['PANOSConnector']['connectionId']"
                                                                        }
                                                                    },
                                                                    "method": "put",
                                                                    "path": "/restapi/v10.0/Policies/SecurityRules",
                                                                    "queries": {
                                                                        "location": "vsys",
                                                                        "name": "@parameters('SecurityPolicyRule')",
                                                                        "vsys": "vsys1"
                                                                    }
                                                                },
                                                                "description": "Add address objects to security policy rules"
                                                            },
                                                            "Append_destination_member_for_new_URL": {
                                                                "runAfter": {
                                                                    "Check_if_address_object_exists__for_block_URL_action": [
                                                                        "Succeeded"
                                                                    ]
                                                                },
                                                                "type": "AppendToArrayVariable",
                                                                "inputs": {
