{
    "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
    "contentVersion": "1.0.0.0",
    "metadata": {
        "title": "Block IP - Cisco ASA",
        "prerequisitesDeployTemplateFile": "../CustomConnector/azuredeploy.json",
        "description": "This playbook allows blocking/allowing of IPs in Cisco ASA, using a Network Object Group. The Network Object Group itself should be part of an Access Control Entry.",
        "prerequisites": [
            "1. In Cisco ASA there needs to be a Network Object Group. You can create a Network Object Group using Cisco ASDM, [Configure a Network Object Group](https://www.cisco.com/c/en/us/td/docs/security/asa/asa96/asdm76/firewall/asdm-76-firewall-config/access-objects.html#ariaid-title6), or using the CLI, [Configuring a Network Object Group](https://www.cisco.com/c/en/us/td/docs/security/asa/asa90/configuration/guide/asa_90_cli_config/acl_objects.html#86292). The Network Object Group can be blocked using an access rule, [Configure Access Rules](https://www.cisco.com/c/en/us/td/docs/security/asa/asa96/asdm76/firewall/asdm-76-firewall-config/access-rules.html#ID-2124-00000152).",
            "2. Cisco ASA custom connector needs to be deployed prior to the deployment of this playbook (link below), in the same resource group and region.",
            "3. To authenticate the connector, in Cisco ASA create a local user and allow it to use the REST API. Depending on the playbook used the user needs to be able to add members to a network object group or create access control entries, by default that requires privilege level 15."
        ],
        "postDeployment": [ "**a. Authorize connections**", "Once deployment is complete, you will need to authorize each connection.", "1. Click the Azure Sentinel connection resource", "2.Click edit API connection", "3.Click Authorize", "4.Sign in", "5.Click Save", "6.Repeat steps for other connections such as Teams and Cisco ASA (For authorizing the Cisco ASA API connection, the username and password needs to be provided)", "**b. Select Teams channel**", "The Teams channel to which the adaptive card will be posted will need to be configured.", "1. Click the Azure Logic app resource", "2. Edit the Logic App", "3. Find the 'PostToTeams' action", "4. Select a Team and Channel", "5. Save the Logic App", "**c. Configurations in Sentinel**", "1. In Azure sentinel analytical rules should be configured to trigger an incident with IP Entity.", "2. Configure the automation rules to trigger this playbook" ],
        "lastUpdateTime": "2021-07-28T00:00:00.000Z",
        "entities": [ "Ip" ],
        "tags": [ "Remediation", "Response from teams" ],
        "support": {
            "tier": "community" 
        },
        "author": {
            "name": "Wortell"
        },
        "releaseNotes": [
            {
                "version": "1.0.0",
                "title": "",
                "notes": [
                    "Initial version"
                ]
            }
        ]
    },
    "parameters": {
        "PlaybookName": {
            "defaultValue": "CiscoASA-AddIPtoNetworkObjectGroup",
            "type": "String",
            "metadata": {
                "description": "Name of the Logic Apps resource to be created"
            }
        },
        "Cisco ASA Connector name": {
            "defaultValue": "CiscoASAConnector",
            "type": "String",
            "metadata": {
                "description": "Cisco ASA Connector name"
            }
        },
        "Network Object Group object ID": {
            "type": "String",
            "metadata": {
                "description": "Network Object Group object ID"
            }
        }
    },
    "variables": {
        "AzureSentinelConnectionName": "[concat('azuresentinel-', parameters('PlaybookName'))]",
        "TeamsConnectionName": "[concat('teamsconnector-', parameters('PlaybookName'))]",
        "CiscoASAConnectionName": "[concat('ciscoasaconnector-', parameters('PlaybookName'))]"
    },
    "resources": [
        {
            "type": "Microsoft.Web/connections",
            "apiVersion": "2016-06-01",
            "name": "[variables('AzureSentinelConnectionName')]",
            "location": "[resourceGroup().location]",
            "kind": "V1",
            "properties": {
                "displayName": "[variables('AzureSentinelConnectionName')]",
                "customParameterValues": {},
                "parameterValueType": "Alternative",
                "api": {
                    "id": "[concat('/subscriptions/', subscription().subscriptionId, '/providers/Microsoft.Web/locations/', resourceGroup().location, '/managedApis/azuresentinel')]"
                }
            }
        },
        {
            "type": "Microsoft.Web/connections",
            "apiVersion": "2016-06-01",
            "name": "[variables('TeamsConnectionName')]",
            "location": "[resourceGroup().location]",
            "properties": {
                "customParameterValues": {},
                "api": {
                    "id": "[concat('/subscriptions/', subscription().subscriptionId, '/providers/Microsoft.Web/locations/', resourceGroup().location, '/managedApis/teams')]"
                }
            }
        },
        {
            "type": "Microsoft.Web/connections",
            "apiVersion": "2016-06-01",
            "name": "[variables('CiscoASAConnectionName')]",
            "location": "[resourceGroup().location]",
            "properties": {
                "customParameterValues": {},
                "api": {
                    "id": "[concat('/subscriptions/', subscription().subscriptionId, '/resourceGroups/', resourceGroup().name, '/providers/Microsoft.Web/customApis/', parameters('Cisco ASA Connector name'))]"
                }
            }
        },
        {
            "type": "Microsoft.Logic/workflows",
            "apiVersion": "2017-07-01",
            "name": "[parameters('PlaybookName')]",
            "location": "[resourceGroup().location]",
            "dependsOn": [
                "[resourceId('Microsoft.Web/connections', variables('AzureSentinelConnectionName'))]",
                "[resourceId('Microsoft.Web/connections', variables('TeamsConnectionName'))]",
                "[resourceId('Microsoft.Web/connections', variables('CiscoASAConnectionName'))]"
            ],
            "tags": {
                "hidden-SentinelTemplateName": "BlockIP-CiscoASA-NetworkObjectGroup",
                "hidden-SentinelTemplateVersion": "1.0"
            },
            "identity": {
                "type": "SystemAssigned"
            },
            "properties": {
                "state": "Enabled",
                "definition": {
                    "$schema": "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#",
                    "contentVersion": "1.0.0.0",
                    "parameters": {
                        "$connections": {
                            "defaultValue": {},
                            "type": "Object"
                        },
                        "Network Object Group object ID": {
                            "defaultValue": "",
                            "type": "String"
                        }
                    },
                    "staticResults": {
                        "Add_comment_to_incident_(V3)0": {
                            "status": "Succeeded",
                            "outputs": {
                                "headers": {},
                                "statusCode": "OK"
                            }
                        },
                        "Entities_-_Get_IPs0": {
                            "status": "Succeeded",
                            "outputs": {
                                "body": {
                                    "IPs": [
                                        {
                                            "Address": "192.168.11.1"
                                        },
                                        {
                                            "Address": "192.168.11.2"
                                        },
                                        {
                                            "Address": "192.168.11.3"
                                        }
                                    ]
                                },
                                "headers": {},
                                "statusCode": "OK"
                            }
                        }
                    },
                    "triggers": {
                        "When_Azure_Sentinel_incident_creation_rule_was_triggered_(Private_Preview_only)": {
                            "type": "ApiConnectionWebhook",
                            "inputs": {
                                "body": {
                                    "callback_url": "@{listCallbackUrl()}"
                                },
                                "host": {
                                    "connection": {
                                        "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                    }
                                },
                                "path": "/incident-creation"
                            }
                        }
                    },
                    "actions": {
                        "Entities_-_Get_IPs": {
                            "runAfter": {},
                            "type": "ApiConnection",
                            "inputs": {
                                "body": "@triggerBody()?['object']?['properties']?['relatedEntities']",
                                "host": {
                                    "connection": {
                                        "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                    }
                                },
                                "method": "post",
                                "path": "/entities/ip"
                            },
                            "runtimeConfiguration": {
                                "staticResult": {
                                    "staticResultOptions": "Disabled",
                                    "name": "Entities_-_Get_IPs0"
                                }
                            }
                        },
                        "Fetch_a_network_object_group": {
                            "runAfter": {
                                "Initialize_Network_Object_Group_object_ID_variable": [
                                    "Succeeded"
                                ]
                            },
                            "type": "ApiConnection",
                            "inputs": {
                                "headers": {
                                    "User-Agent": "REST API Agent"
                                },
                                "host": {
                                    "connection": {
                                        "name": "@parameters('$connections')['cisco-ASAv-connector']['connectionId']"
                                    }
                                },
                                "method": "get",
                                "path": "/api/objects/networkobjectgroups/@{encodeURIComponent(variables('Network Object Group object ID'))}"
                            }
                        },
                        "For_each_over_IPs": {
                            "foreach": "@body('Entities_-_Get_IPs')?['IPs']",
                            "actions": {
                                "Append_to_ipAddresses_variable": {
                                    "runAfter": {
                                        "If_Network_Object_Group_contains_IP": [
                                            "Succeeded"
                                        ]
                                    },
                                    "type": "AppendToArrayVariable",
                                    "inputs": {
                                        "name": "ipAddresses",
                                        "value": {
                                            "IPAddress": "@{items('For_each_over_IPs')?['Address']}",
                                            "controlName": "ipAddressAction@{variables('forEachIndex')}",
                                            "existsInNetworkObjectGroup": "@if(greater(length(body('Filter_Network_Object_Group_Members_for_IP_Address')), 0), true, false)"
                                        }
                                    }
                                },
                                "Filter_Network_Object_Group_Members_for_IP_Address": {
                                    "runAfter": {},
                                    "type": "Query",
                                    "inputs": {
                                        "from": "@body('Fetch_a_network_object_group')?['members']",
                                        "where": "@and(equals(item()?['kind'], 'IPv4Address'), equals(item()?['value'], items('For_each_over_IPs')?['Address']))"
                                    }
                                },
                                "If_Network_Object_Group_contains_IP": {
                                    "actions": {
                                        "Append_to_adaptiveCardIPAddressItems_variable_remove_block": {
                                            "runAfter": {},
                                            "type": "AppendToArrayVariable",
                                            "inputs": {
                                                "name": "adaptiveCardIPAddressItems",
                                                "value": {
                                                    "columns": [
                                                        {
                                                            "items": [
                                                                {
                                                                    "text": "Unblock '@{items('For_each_over_IPs')?['Address']}'?",
                                                                    "type": "TextBlock",
                                                                    "wrap": true
                                                                }
                                                            ],
                                                            "type": "Column",
                                                            "width": "stretch"
                                                        },
                                                        {
                                                            "items": [
                                                                {
                                                                    "choices": [
                                                                        {
                                                                            "title": "Ignore",
                                                                            "value": "ignore"
                                                                        },
                                                                        {
                                                                            "title": "Unblock",
                                                                            "value": "unblock"
                                                                        }
                                                                    ],
                                                                    "id": "ipAddressAction@{variables('forEachIndex')}",
                                                                    "placeholder": "Placeholder text",
                                                                    "type": "Input.ChoiceSet",
                                                                    "value": "ignore"
                                                                }
                                                            ],
                                                            "type": "Column",
                                                            "width": "stretch"
                                                        }
                                                    ],
                                                    "type": "ColumnSet"
                                                }
                                            }
                                        }
                                    },
                                    "runAfter": {
                                        "Filter_Network_Object_Group_Members_for_IP_Address": [
                                            "Succeeded"
                                        ]
                                    },
                                    "else": {
                                        "actions": {
                                            "Append_to_adaptiveCardIPAddressItems_variable_add_block": {
                                                "runAfter": {},
                                                "type": "AppendToArrayVariable",
                                                "inputs": {
                                                    "name": "adaptiveCardIPAddressItems",
                                                    "value": {
                                                        "columns": [
                                                            {
                                                                "items": [
                                                                    {
                                                                        "text": "Block '@{items('For_each_over_IPs')?['Address']}'?",
                                                                        "type": "TextBlock",
                                                                        "wrap": true
                                                                    }
                                                                ],
                                                                "type": "Column",
                                                                "width": "stretch"
                                                            },
                                                            {
                                                                "items": [
                                                                    {
                                                                        "choices": [
                                                                            {
                                                                                "title": "Ignore",
                                                                                "value": "ignore"
                                                                            },
                                                                            {
                                                                                "title": "Block",
                                                                                "value": "block"
                                                                            }
                                                                        ],
                                                                        "id": "ipAddressAction@{variables('forEachIndex')}",
                                                                        "placeholder": "Placeholder text",
                                                                        "type": "Input.ChoiceSet",
                                                                        "value": "ignore"
                                                                    }
                                                                ],
                                                                "type": "Column",
                                                                "width": "stretch"
                                                            }
                                                        ],
                                                        "type": "ColumnSet"
                                                    }
                                                }
                                            }
                                        }
                                    },
                                    "expression": {
                                        "and": [
                                            {
                                                "greater": [
                                                    "@length(body('Filter_Network_Object_Group_Members_for_IP_Address'))",
                                                    0
                                                ]
                                            }
                                        ]
                                    },
                                    "type": "If"
                                },
                                "Increment_for_For_Each_index": {
                                    "runAfter": {
                                        "Append_to_ipAddresses_variable": [
                                            "Succeeded"
                                        ]
                                    },
                                    "type": "IncrementVariable",
                                    "inputs": {
                                        "name": "forEachIndex",
                                        "value": 1
                                    }
                                }
                            },
                            "runAfter": {
                                "Initialize_For_Each_index_variable": [
                                    "Succeeded"
                                ]
                            },
                            "type": "Foreach",
                            "runtimeConfiguration": {
                                "concurrency": {
                                    "repetitions": 1
                                }
                            }
                        },
                        "If_PostToTeams_submit_action_is_Submit": {
                            "actions": {
                                "Add_comment_to_incident_(V3)": {
                                    "runAfter": {
                                        "For_each_over_ipAddresses": [
                                            "Succeeded"
                                        ]
                                    },
                                    "type": "ApiConnection",
                                    "inputs": {
                                        "body": {
                                            "incidentArmId": "@triggerBody()?['object']?['id']",
                                            "message": "<p><span style=\"font-size: 16px\"><strong>Cisco ASA playbook run summary</strong></span><br>\n<span style=\"font-size: 14px\">The following IPs were found in the Incident:</span><br>\n@{variables('ipAddressesActionComment')}</p>"
                                        },
                                        "host": {
                                            "connection": {
                                                "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                            }
                                        },
                                        "method": "post",
                                        "path": "/Incidents/Comment"
                                    },
                                    "runtimeConfiguration": {
                                        "staticResult": {
                                            "staticResultOptions": "Disabled",
                                            "name": "Add_comment_to_incident_(V3)0"
                                        }
                                    }
                                },
                                "For_each_over_ipAddresses": {
                                    "foreach": "@variables('ipAddresses')",
                                    "actions": {
                                        "Switch_PostToTeams_data_for_IP_Address": {
                                            "runAfter": {},
                                            "cases": {
                                                "Case_block": {
                                                    "case": "block",
                                                    "actions": {
                                                        "Append_blocked_comment_to_ipAddressActionComment": {
                                                            "runAfter": {
                                                                "Patch_members_of_a_network_object_group_to_add_IPAddress": [
                                                                    "Succeeded"
                                                                ]
                                                            },
                                                            "type": "AppendToStringVariable",
                                                            "inputs": {
                                                                "name": "ipAddressesActionComment",
                                                                "value": "@{items('For_each_over_ipAddresses')['IPAddress']} - blocked in Cisco ASA\n"
                                                            }
                                                        },
                                                        "Patch_members_of_a_network_object_group_to_add_IPAddress": {
                                                            "runAfter": {},
                                                            "type": "ApiConnection",
                                                            "inputs": {
                                                                "body": {
                                                                    "members.add": [
                                                                        {
                                                                            "kind": "IPv4Address",
                                                                            "value": "@{items('For_each_over_ipAddresses')['IPAddress']}"
                                                                        }
                                                                    ]
                                                                },
                                                                "headers": {
                                                                    "User-Agent": "REST API Agent"
                                                                },
                                                                "host": {
                                                                    "connection": {
                                                                        "name": "@parameters('$connections')['cisco-ASAv-connector']['connectionId']"
                                                                    }
                                                                },
                                                                "method": "patch",
                                                                "path": "/api/objects/networkobjectgroups/@{encodeURIComponent(variables('Network Object Group object ID'))}"
                                                            }
                                                        }
                                                    }
                                                },
                                                "Case_unblock": {
                                                    "case": "unblock",
                                                    "actions": {
                                                        "Append_unblocked_comment_to_ipAddressActionComment": {
                                                            "runAfter": {
                                                                "Patch_members_of_a_network_object_group_to_remove_IPAddress": [
                                                                    "Succeeded"
                                                                ]
                                                            },
                                                            "type": "AppendToStringVariable",
                                                            "inputs": {
                                                                "name": "ipAddressesActionComment",
                                                                "value": "@{items('For_each_over_ipAddresses')['IPAddress']} - unblocked in Cisco ASA\n"
                                                            }
                                                        },
                                                        "Patch_members_of_a_network_object_group_to_remove_IPAddress": {
                                                            "runAfter": {},
                                                            "type": "ApiConnection",
                                                            "inputs": {
                                                                "body": {
                                                                    "members.remove": [
                                                                        {
                                                                            "kind": "IPv4Address",
                                                                            "value": "@{items('For_each_over_ipAddresses')['IPAddress']}"
                                                                        }
                                                                    ]
                                                                },
                                                                "headers": {
                                                                    "User-Agent": "REST API Agent"
                                                                },
                                                                "host": {
                                                                    "connection": {
                                                                        "name": "@parameters('$connections')['cisco-ASAv-connector']['connectionId']"
                                                                    }
                                                                },
                                                                "method": "patch",
                                                                "path": "/api/objects/networkobjectgroups/@{encodeURIComponent(variables('Network Object Group object ID'))}"
                                                            }
                                                        }
                                                    }
                                                }
                                            },
                                            "default": {
                                                "actions": {
                                                    "Append_no_action_taken_comment_to_ipAddressActionComment": {
                                                        "runAfter": {},
                                                        "type": "AppendToStringVariable",
                                                        "inputs": {
                                                            "name": "ipAddressesActionComment",
                                                            "value": "@{items('For_each_over_ipAddresses')['IPAddress']} - no action taken in Cisco ASA\n"
                                                        }
                                                    }
                                                }
                                            },
                                            "expression": "@outputs('PostToTeams')['body']['data'][item()['controlName']]",
                                            "type": "Switch"
                                        }
                                    },
                                    "runAfter": {},
                                    "type": "Foreach"
                                },
                                "Update_incident": {
                                    "runAfter": {
                                        "Add_comment_to_incident_(V3)": [
                                            "Succeeded"
                                        ]
                                    },
                                    "type": "ApiConnection",
                                    "inputs": {
                                        "body": {
                                            "classification": {
                                                "ClassificationAndReason": "@{outputs('PostToTeams')['body']['data']['incidentStatus']}"
                                            },
                                            "incidentArmId": "@triggerBody()?['object']?['id']",
                                            "severity": "@{outputs('PostToTeams')['body']['data']['incidentSeverity']}",
                                            "status": "Closed"
                                        },
                                        "host": {
                                            "connection": {
                                                "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                            }
                                        },
                                        "method": "put",
                                        "path": "/Incidents"
                                    }
                                }
                            },
                            "runAfter": {
                                "Initialize_ipAddressesActionComment_variable": [
                                    "Succeeded"
                                ]
                            },
                            "expression": {
                                "and": [
                                    {
                                        "equals": [
                                            "@outputs('PostToTeams')['body']['submitActionId']",
                                            "Submit"
                                        ]
                                    }
                                ]
                            },
                            "type": "If"
                        },
                        "Initialize_Adaptive_Card_IP_Address_variable": {
                            "runAfter": {
                                "Initialize_ipAddresses_variable": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "adaptiveCardIPAddressItems",
                                        "type": "array"
                                    }
                                ]
                            }
                        },
                        "Initialize_For_Each_index_variable": {
                            "runAfter": {
                                "Initialize_Adaptive_Card_IP_Address_variable": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "forEachIndex",
                                        "type": "integer",
                                        "value": 0
                                    }
                                ]
                            }
                        },
                        "Initialize_Network_Object_Group_object_ID_variable": {
                            "runAfter": {
                                "Entities_-_Get_IPs": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "Network Object Group object ID",
                                        "type": "string",
                                        "value": "@parameters('Network Object Group object ID')"
                                    }
                                ]
                            }
                        },
                        "Initialize_ipAddressesActionComment_variable": {
                            "runAfter": {
