                            "runAfter": {
                              "Filter_array_all_the_breaches": [
                                "Succeeded"
                              ]
                            },
                            "type": "SetVariable",
                            "inputs": {
                              "name": "ActionTaken",
                              "value": "No action taken by SOC."
                            },
                            "description": "This sets the action taken variable if Ignored"
                          },
                          "Set_variable_consolidate_Info_if_ignored": {
                            "runAfter": {
                              "Set_variable_SOC_decision_if_ignored": [
                                "Succeeded"
                              ]
