                                                                "properties": {
                                                                    "access": "Deny",
                                                                    "destinationAddressPrefix": "*",
                                                                    "destinationAddressPrefixes": [],
                                                                    "destinationPortRange": "*",
                                                                    "destinationPortRanges": [],
                                                                    "direction": "Outbound",
                                                                    "priority": 1000,
                                                                    "protocol": "*",
                                                                    "sourceAddressPrefix": "*",
                                                                    "sourceAddressPrefixes": [],
                                                                    "sourcePortRange": "*",
                                                                    "sourcePortRanges": []
                                                                }
                                                            }
                                                        ]
                                                    }
                                                },
                                                "method": "PUT",
                                                "uri": "https://management.azure.com/subscriptions/@{split(body('Parse_JSON')?['id'], '/')[add(length(split(body('Parse_JSON')?['id'], '/')), -7)]}/resourceGroups/@{split(body('Parse_JSON')?['id'], '/')[add(length(split(body('Parse_JSON')?['id'], '/')), -5)]}/providers/Microsoft.Network/networkSecurityGroups/@{guid()}?api-version=2019-11-01"
                                            }
                                        },
                                        "HTTP_6": {
                                            "runAfter": {
                                                "Condition": [
                                                    "Succeeded"
                                                ]
                                            },
                                            "type": "Http",
                                            "inputs": {
                                                "authentication": {
                                                    "audience": "https://management.azure.com/",
                                                    "type": "ManagedServiceIdentity"
                                                },
                                                "body": "@variables('nicputrequest')",
                                                "method": "PUT",
                                                "uri": "https://management.azure.com/@{body('HTTP_3')?['properties']?['networkProfile']?['networkInterfaces'][0]?['id']}?api-version=2019-11-01"
                                            }
                                        },
                                        "HTTP_7": {
                                            "runAfter": {
                                                "HTTP_6": [
                                                    "Succeeded"
                                                ]
                                            },
                                            "type": "Http",
                                            "inputs": {
                                                "authentication": {
                                                    "audience": "https://management.azure.com/",
                                                    "type": "ManagedServiceIdentity"
                                                },
                                                "method": "POST",
                                                "uri": "https://management.azure.com/@{variables('vmid')}/restart?api-version=2019-07-01"
                                            }
                                        },
                                        "Parse_JSON": {
                                            "runAfter": {
                                                "HTTP_4": [
                                                    "Succeeded"
                                                ]
                                            },
                                            "type": "ParseJson",
                                            "inputs": {
                                                "content": "@body('HTTP_4')",
                                                "schema": {
                                                    "properties": {
                                                        "id": {
                                                            "type": "string"
                                                        },
                                                        "location": {
                                                            "type": "string"
                                                        },
                                                        "name": {
                                                            "type": "string"
                                                        },
                                                        "properties": {
                                                            "properties": {
                                                                "hostedWorkloads": {
                                                                    "type": "array"
                                                                },
                                                                "ipConfigurations": {
                                                                    "items": {
                                                                        "properties": {
                                                                            "etag": {
                                                                                "type": "string"
                                                                            },
                                                                            "id": {
                                                                                "type": "string"
                                                                            },
                                                                            "name": {
                                                                                "type": "string"
