                            "inputs": {
                                "variables": [
                                    {
                                        "name": "vmlocation",
                                        "type": "string",
                                        "value": "@{null}"
                                    }
                                ]
                            }
                        },
                        "Initialize_variable_3": {
                            "runAfter": {
                                "Initialize_variable_2": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "nicputrequest",
                                        "type": "object",
                                        "value": {}
                                    }
                                ]
