{
    "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
    "contentVersion": "1.0.0.0",
    "metadata": {
        "title": "Enrichment URL - Forcepoint",
        "description": "This playbook checks if malicious URL is blocked or unblocked by SMC firewall.",
        "mainSteps": [ "1. Fetches a list of potentially malicious URLs", "2. Enrich the incident with URL status information." ],
        "prerequisites": [
            "1. Forcepoint SMC Custom Connector needs to be deployed prior to the deployment of this playbook under the same resource group.",
            "2. Forcepoint SMC API Key should be known.[Refer here](http://www.websense.com/content/support/library/ngfw/v610/rfrnce/ngfw_6100_ug_smc-api_a_en-us.pdf )",
            "3. Forcepoint SMC Version number should be known. [Refer here](https://help.stonesoft.com/onlinehelp/StoneGate/SMC/)"
        ],
        "prerequisitesDeployTemplateFile": "../../ForcepointSMCApiConnector/azuredeploy.json",
        "lastUpdateTime": "2021-07-26T00:00:00.000Z",
        "entities": [ "Url" ],
        "tags": [ "Enrichment" ],
        "support": {
            "tier": "community"
        },
        "author": {
            "name": "Accenture"
        }
    },
    "parameters": {
        "PlaybookName": {
            "type": "String",
            "defaultValue": "EnrichmentURL-ForcepointNGFW",
            "metadata": {
                "description": "Enter name for playbook without spaces. This playbook will enrich URL status information."
            }
        },
        "ForcepointSMCConnectorName": {
            "type": "string",
            "defaultValue": "ForcepointSMC-Connector",
            "metadata": {
                "description": "Enter the name for your Forcepoint SMC Connector without spaces"
            }
        },
        "ForcepointSMCApiKey": {
            "type": "securestring",
            "metadata": {
                "description": "Enter the api key for smc login"
            }
        },
        "VersionNumber": {
            "type": "string",
            "defaultValue": "6.8",
            "metadata": {
                "description": "Enter SMC Version Number"
            }
        }
    },
    "variables": {
        "Forcepoint_Connector": "[concat('ForcepointSMCApiConnector-',parameters('PlaybookName'))]",
        "azureSentinel_Connection": "[concat('azuresentienl-',parameters('PlaybookName'))]"
    },
    "resources": [
        {
            "type": "Microsoft.Logic/workflows",
            "apiVersion": "2017-07-01",
            "name": "[parameters('PlaybookName')]",
            "location": "[resourceGroup().location]",
            "dependsOn": [
                "[resourceId('Microsoft.Web/connections', variables('Forcepoint_Connector'))]",
                "[resourceId('Microsoft.Web/connections', variables('azureSentinel_Connection'))]"
            ],
            "identity": {
                "type": "SystemAssigned"
            },
            "properties": {
                "state": "Enabled",
                "definition": {
                    "$schema": "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#",
                    "contentVersion": "1.0.0.0",
                    "parameters": {
                        "$connections": {
                            "defaultValue": {},
                            "type": "Object"
                        }
                    },
                    "triggers": {
                        "Microsoft_Sentinel_incident": {
                            "type": "ApiConnectionWebhook",
                            "inputs": {
                                "body": {
                                    "callback_url": "@{listCallbackUrl()}"
                                },
                                "host": {
                                    "connection": {
                                        "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                    }
                                },
                                "path": "/incident-creation"
                            }
                        }
                    },
                    "actions": {
                        "Check_if_body_present_from_output": {
                            "actions": {
                                "Check_Login_Status": {
                                    "runAfter": {
                                        "Login": [
                                            "Succeeded",
                                            "Failed",
                                            "Skipped",
                                            "TimedOut"
                                        ]
                                    },
                                    "cases": {
                                        "200_Success_OK": {
                                            "case": 200,
                                            "actions": {
                                                "Condition_to_check_if_needs_to_be_terminated": {
                                                    "actions": {
                                                        "Terminate_the_playbook_if_API_issue_occurred": {
                                                            "runAfter": {},
                                                            "type": "Terminate",
                                                            "inputs": {
                                                                "runError": {
                                                                    "message": "Having API issue in playbook"
                                                                },
                                                                "runStatus": "Failed"
                                                            },
                                                            "description": "Terminate the playbook if API issue occurred"
                                                        }
                                                    },
                                                    "runAfter": {
                                                        "Create_HTML_table_for_Add_comment_to_incident": [
                                                            "Succeeded",
                                                            "TimedOut",
                                                            "Skipped",
                                                            "Failed"
                                                        ]
                                                    },
                                                    "else": {
                                                        "actions": {
                                                            "Add_comment_to_incident_(V3)": {
                                                                "runAfter": {},
                                                                "type": "ApiConnection",
                                                                "inputs": {
                                                                    "body": {
                                                                        "incidentArmId": "@triggerBody()?['object']?['id']",
                                                                        "message": "<p>@{outputs('Forcepoint_Logo')}<strong>Forcepoint NGFW-Enrichment URL</strong><br>\nList of policies associated by incident Url(s)<br>\n<br>\n@{body('Create_HTML_table_for_Add_comment_to_incident')}<br>\n<br>\n</p>"
                                                                    },
                                                                    "host": {
                                                                        "connection": {
                                                                            "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                                                        }
                                                                    },
                                                                    "method": "post",
                                                                    "path": "/Incidents/Comment"
                                                                }
                                                            }
                                                        }
                                                    },
                                                    "expression": {
                                                        "and": [
                                                            {
                                                                "equals": [
                                                                    "@variables('Terminate')",
                                                                    "APIError"
                                                                ]
                                                            }
                                                        ]
                                                    },
                                                    "type": "If",
                                                    "description": "Condition to check if needs to be terminated"
                                                },
                                                "Create_HTML_table_for_Add_comment_to_incident": {
                                                    "runAfter": {
                                                        "For_each_for_not_found_URL": [
                                                            "Succeeded"
                                                        ]
                                                    },
                                                    "type": "Table",
                                                    "inputs": {
                                                        "columns": [
                                                            {
                                                                "header": "URL",
                                                                "value": "@item()?['URLAddres']"
                                                            },
                                                            {
                                                                "header": "URL-Element-Name",
                                                                "value": "@item()?['Elementname']"
                                                            },
                                                            {
                                                                "header": "URL-Element-Type",
                                                                "value": "@item()?['Type']"
                                                            },
                                                            {
                                                                "header": "Policy-Name",
                                                                "value": "@item()?['Policy']"
                                                            },
                                                            {
                                                                "header": "Policy-Type",
                                                                "value": "@item()?['Policytype']"
                                                            },
                                                            {
                                                                "header": "URL-Status",
                                                                "value": "@item()?['URLStatus']"
                                                            },
                                                            {
                                                                "header": "Action",
                                                                "value": "@item()?['Action']"
                                                            }
                                                        ],
                                                        "format": "HTML",
                                                        "from": "@variables('Arrayforallactions')"
                                                    },
                                                    "description": "Creating a HTML table from all actions taken by URL"
                                                },
                                                "For_each_URL_list": {
                                                    "foreach": "@body('Get_URL_List')?['result']",
                                                    "actions": {
                                                        "Get_URLs_from_URL_list": {
                                                            "runAfter": {},
                                                            "type": "ApiConnection",
                                                            "inputs": {
                                                                "headers": {
                                                                    "Accept": "application/json",
                                                                    "Content-Type": "application/json"
                                                                },
                                                                "host": {
                                                                    "connection": {
                                                                        "name": "@parameters('$connections')['ForcepointSMCApiConnector']['connectionId']"
                                                                    }
                                                                },
                                                                "method": "get",
                                                                "path": "/@{encodeURIComponent(variables('SMC Api Version Number'))}/elements/url_list_application/@{encodeURIComponent(last(split(items('For_each_URL_list')?['href'],'/')))}"
                                                            }
                                                        },
                                                        "Looping_URL_Address": {
                                                            "foreach": "@body('Entities_-_Get_URLs')?['URLs']",
                                                            "actions": {
                                                                "Check_the_result_length_from_filter_output": {
                                                                    "actions": {
                                                                        "Append_to_element_names_to_element_variable": {
                                                                            "runAfter": {
                                                                                "Set_consolidate_variable_if_URL__present_in_URL_list": [
                                                                                    "Succeeded"
                                                                                ]
                                                                            },
                                                                            "type": "AppendToArrayVariable",
                                                                            "inputs": {
                                                                                "name": "Elements",
                                                                                "value": "@variables('Consolidatevrbl')"
                                                                            },
                                                                            "description": "Append to element names to element variable"
                                                                        },
                                                                        "Set_consolidate_variable_if_URL__present_in_URL_list": {
                                                                            "runAfter": {},
                                                                            "type": "SetVariable",
                                                                            "inputs": {
                                                                                "name": "Consolidatevrbl",
                                                                                "value": {
                                                                                    "Element": "@{items('For_each_URL_list')?['name']}",
                                                                                    "Type": "URL List",
                                                                                    "URL": "@{items('Looping_URL_Address')?['Url']}"
                                                                                }
                                                                            },
                                                                            "description": "Set consolidate variable if URL  present in URL list"
                                                                        }
                                                                    },
                                                                    "runAfter": {},
                                                                    "expression": {
                                                                        "and": [
                                                                            {
                                                                                "contains": [
                                                                                    "@body('Get_URLs_from_URL_list')?['url_entry']",
                                                                                    "@items('Looping_URL_Address')?['Url']"
                                                                                ]
                                                                            }
                                                                        ]
                                                                    },
                                                                    "type": "If",
                                                                    "description": "We will check for the result output is empty or exist in the policy rule. If result output is empty ,then there is no policy based on  URL. And If result ouput is having some information related to URL then there is a policy with respect to URL"
                                                                }
                                                            },
                                                            "runAfter": {
                                                                "Get_URLs_from_URL_list": [
                                                                    "Succeeded",
                                                                    "TimedOut",
                                                                    "Skipped",
                                                                    "Failed"
                                                                ]
                                                            },
                                                            "type": "Foreach",
                                                            "description": "Here we are looping each URL Address and check whether it is blocked or not "
                                                        }
                                                    },
                                                    "runAfter": {
                                                        "Get_URL_List": [
                                                            "Succeeded",
                                                            "TimedOut",
                                                            "Skipped",
                                                            "Failed"
                                                        ]
                                                    },
                                                    "type": "Foreach",
                                                    "description": "For each URL list"
                                                },
                                                "For_each_element": {
                                                    "foreach": "@outputs('Remove_duplicates')",
                                                    "actions": {
                                                        "Condition_to_check_if_element_is_part_any_policy": {
                                                            "actions": {
                                                                "For_each_element_type": {
                                                                    "foreach": "@body('Find_IP_or_URL_in_SMC')?['element']",
                                                                    "actions": {
                                                                        "Bind_element_type": {
                                                                            "runAfter": {},
                                                                            "type": "Compose",
                                                                            "inputs": "@items('For_each_element_type')?['link']?[0]?['type']"
                                                                        },
                                                                        "Condition_to_check_element_type": {
                                                                            "actions": {
                                                                                "Append_to_all_actions_array_if_element_is_part_of_any_policy": {
                                                                                    "runAfter": {
                                                                                        "Set_consolidate_variable_if_element_is_part_of_any_policy": [
                                                                                            "Succeeded"
                                                                                        ]
                                                                                    },
                                                                                    "type": "AppendToArrayVariable",
                                                                                    "inputs": {
                                                                                        "name": "Arrayforallactions",
                                                                                        "value": "@variables('Consolidatevrbl')"
                                                                                    },
                                                                                    "description": "Append to all actions array if element is part of any policy"
                                                                                },
                                                                                "Set_consolidate_variable_if_element_is_part_of_any_policy": {
                                                                                    "runAfter": {},
                                                                                    "type": "SetVariable",
                                                                                    "inputs": {
                                                                                        "name": "Consolidatevrbl",
                                                                                        "value": {
                                                                                            "Action": "Found in policy and URL  is blocked state",
                                                                                            "Elementname": "@{items('For_each_element')?['Element']}",
                                                                                            "IncidentSeverity": "@{triggerBody()?['object']?['properties']?['severity']}",
                                                                                            "Policy": "@{items('For_each_element_type')?['name']}",
                                                                                            "Policytype": "@{outputs('Bind_element_type')}",
                                                                                            "Type": "@{items('For_each_element')?['Type']}",
                                                                                            "URLAddres": "@{items('For_each_element')?['URL']}",
                                                                                            "URLStatus": "Blocked"
                                                                                        }
                                                                                    },
                                                                                    "description": "Set consolidate variable if element is part of any policy"
                                                                                }
                                                                            },
                                                                            "runAfter": {
                                                                                "Bind_element_type": [
                                                                                    "Succeeded",
                                                                                    "TimedOut",
                                                                                    "Skipped",
                                                                                    "Failed"
                                                                                ]
                                                                            },
                                                                            "else": {
                                                                                "actions": {
                                                                                    "Append_to_URL__array_": {
                                                                                        "runAfter": {
                                                                                            "Set_consolidate_variable_if_URL_is_present_list_or_host": [
                                                                                                "Succeeded"
                                                                                            ]
                                                                                        },
                                                                                        "type": "AppendToArrayVariable",
                                                                                        "inputs": {
                                                                                            "name": "URL Address",
                                                                                            "value": "@variables('Consolidatevrbl')"
                                                                                        },
                                                                                        "description": "Append to URL  array "
                                                                                    },
                                                                                    "Set_consolidate_variable_if_URL_is_present_list_or_host": {
                                                                                        "runAfter": {},
                                                                                        "type": "SetVariable",
                                                                                        "inputs": {
                                                                                            "name": "Consolidatevrbl",
                                                                                            "value": {
                                                                                                "Elementname": "@{outputs('Bind_element_type')}",
                                                                                                "Name": "@{items('For_each_element_type')?['name']}",
                                                                                                "Type": "@{items('For_each_element')?['Type']}",
                                                                                                "URLAddres": "@{items('For_each_element')?['URL']}"
                                                                                            }
                                                                                        },
                                                                                        "description": "Set consolidate variable if URL is present list or host"
                                                                                    }
                                                                                }
                                                                            },
                                                                            "expression": {
                                                                                "and": [
                                                                                    {
                                                                                        "contains": [
                                                                                            "@outputs('Bind_element_type')",
                                                                                            "_policy"
                                                                                        ]
                                                                                    }
                                                                                ]
                                                                            },
                                                                            "type": "If"
                                                                        }
                                                                    },
                                                                    "runAfter": {},
                                                                    "type": "Foreach"
                                                                }
                                                            },
                                                            "runAfter": {
                                                                "Find_IP_or_URL_in_SMC": [
                                                                    "Succeeded",
                                                                    "TimedOut",
                                                                    "Skipped",
                                                                    "Failed"
                                                                ]
                                                            },
                                                            "expression": {
                                                                "and": [
                                                                    {
                                                                        "equals": [
                                                                            "@outputs('Find_IP_or_URL_in_SMC')?['statusCode']",
                                                                            200
                                                                        ]
                                                                    },
                                                                    {
                                                                        "greater": [
                                                                            "@length(body('Find_IP_or_URL_in_SMC')?['element'])",
                                                                            0
                                                                        ]
                                                                    }
                                                                ]
                                                            },
                                                            "type": "If",
                                                            "description": "Condition to check if element is part any policy"
                                                        },
                                                        "Find_IP_or_URL_in_SMC": {
                                                            "runAfter": {},
                                                            "type": "ApiConnection",
                                                            "inputs": {
                                                                "headers": {
                                                                    "Accept": "application/json",
                                                                    "Content-Type": "application/json"
                                                                },
                                                                "host": {
                                                                    "connection": {
                                                                        "name": "@parameters('$connections')['ForcepointSMCApiConnector']['connectionId']"
                                                                    }
                                                                },
                                                                "method": "get",
                                                                "path": "/@{encodeURIComponent(variables('SMC Api Version Number'))}/elements",
                                                                "queries": {
                                                                    "expand": true,
                                                                    "expose_etag": true,
                                                                    "filter": "@{items('For_each_element')?['Element']}",
                                                                    "flatten": true
                                                                }
                                                            }
                                                        }
                                                    },
                                                    "runAfter": {
                                                        "Remove_duplicates": [
                                                            "Succeeded"
                                                        ]
                                                    },
                                                    "type": "Foreach"
                                                },
                                                "For_each_for_not_found_URL": {
                                                    "foreach": "@body('Entities_-_Get_URLs')?['URLs']",
                                                    "actions": {
                                                        "Condition_to_check_body_of_filter_array": {
                                                            "actions": {},
                                                            "runAfter": {
                                                                "Filter_array": [
                                                                    "Succeeded"
                                                                ]
                                                            },
                                                            "else": {
                                                                "actions": {
                                                                    "Append_to_all_action_array_if_url_not_found": {
                                                                        "runAfter": {
                                                                            "Set_consolidate_variable_if_URL_is_not_found_in_any_policy": [
                                                                                "Succeeded"
                                                                            ]
                                                                        },
                                                                        "type": "AppendToArrayVariable",
                                                                        "inputs": {
                                                                            "name": "Arrayforallactions",
                                                                            "value": "@variables('Consolidatevrbl')"
                                                                        }
                                                                    },
                                                                    "Set_consolidate_variable_if_URL_is_not_found_in_any_policy": {
                                                                        "runAfter": {},
                                                                        "type": "SetVariable",
                                                                        "inputs": {
                                                                            "name": "Consolidatevrbl",
                                                                            "value": {
                                                                                "Action": "Not Found in any policy and URL  is unblocked state",
                                                                                "Elementname": "--",
                                                                                "IncidentSeverity": "@{triggerBody()?['object']?['properties']?['severity']}",
                                                                                "Policy": "--",
                                                                                "Policytype": "--",
                                                                                "Type": "--",
                                                                                "URLAddres": "@{outputs('URL')?['Url']}",
                                                                                "URLStatus": "unblocked"
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            },
                                                            "expression": {
                                                                "and": [
                                                                    {
                                                                        "greater": [
                                                                            "@length(body('Filter_array'))",
                                                                            0
                                                                        ]
                                                                    }
                                                                ]
                                                            },
                                                            "type": "If"
                                                        },
                                                        "Filter_array": {
                                                            "runAfter": {
                                                                "URL": [
                                                                    "Succeeded"
                                                                ]
                                                            },
                                                            "type": "Query",
                                                            "inputs": {
                                                                "from": "@variables('Arrayforallactions')",
                                                                "where": "@contains(item()?['URLAddres'], outputs('URL')?['Url'])"
                                                            }
                                                        },
                                                        "URL": {
                                                            "runAfter": {},
                                                            "type": "Compose",
                                                            "inputs": "@items('For_each_for_not_found_URL')"
                                                        }
                                                    },
                                                    "runAfter": {
                                                        "For_each_element": [
                                                            "Succeeded",
                                                            "TimedOut",
                                                            "Skipped",
                                                            "Failed"
                                                        ]
                                                    },
                                                    "type": "Foreach"
                                                },
                                                "Get_URL_List": {
                                                    "runAfter": {},
                                                    "type": "ApiConnection",
                                                    "inputs": {
                                                        "headers": {
                                                            "Accept": "application/json",
                                                            "Content-Type": "application/json"
                                                        },
                                                        "host": {
                                                            "connection": {
                                                                "name": "@parameters('$connections')['ForcepointSMCApiConnector']['connectionId']"
                                                            }
                                                        },
                                                        "method": "get",
                                                        "path": "/@{encodeURIComponent(variables('SMC Api Version Number'))}/elements/url_list_application"
                                                    }
                                                },
                                                "Remove_duplicates": {
                                                    "runAfter": {
                                                        "For_each_URL_list": [
                                                            "Succeeded",
                                                            "TimedOut",
                                                            "Skipped",
                                                            "Failed"
                                                        ]
                                                    },
                                                    "type": "Compose",
                                                    "inputs": "@union(variables('Elements'),variables('Elements'))"
                                                }
                                            }
                                        }
                                    },
                                    "default": {
                                        "actions": {
                                            "Set_variable_to_login_unsuccessful": {
                                                "runAfter": {},
                                                "type": "SetVariable",
                                                "inputs": {
                                                    "name": "Error",
                                                    "value": "Error status code @{outputs('Login')['statusCode']}Unsuccessful login attempt."
                                                },
                                                "description": "When unsuccessful login atempt has done then we can bind the error to \"Error\" variable."
                                            },
                                            "Terminate_if_login_is_unsuccessful": {
                                                "runAfter": {
                                                    "Set_variable_to_login_unsuccessful": [
                                                        "Succeeded"
                                                    ]
                                                },
                                                "type": "Terminate",
                                                "inputs": {
                                                    "runError": {
                                                        "message": "@variables('Error')"
                                                    },
                                                    "runStatus": "Failed"
                                                },
                                                "description": "Terminate if login is unsuccessful login attempt"
                                            }
                                        }
                                    },
                                    "expression": "@outputs('Login')['statusCode']",
                                    "type": "Switch"
                                },
                                "Login": {
                                    "runAfter": {},
                                    "type": "ApiConnection",
                                    "inputs": {
                                        "body": {
                                            "authenticationkey": "@variables('SMC API Key')"
                                        },
                                        "headers": {
                                            "Accept": "application/json",
                                            "Content-Type": "application/json"
                                        },
                                        "host": {
                                            "connection": {
                                                "name": "@parameters('$connections')['ForcepointSMCApiConnector']['connectionId']"
                                            }
                                        },
                                        "method": "post",
                                        "path": "/@{encodeURIComponent(variables('SMC Api Version Number'))}/login"
                                    },
                                    "description": "Before take an action against to any other api in Forcepoint SMC we need to do login."
                                }
                            },
                            "runAfter": {
                                "Initialize_variable_append_elements_of_URL_": [
                                    "Succeeded"
                                ]
                            },
                            "else": {
                                "actions": {
                                    "Set_variable_to_error_variable_if_URL_Address_are_not_available_from_sentinel": {
                                        "runAfter": {},
                                        "type": "SetVariable",
                                        "inputs": {
                                            "name": "Error",
                                            "value": "URL not found from sentinel incident."
                                        },
                                        "description": "Binding the error to \"Error\" variable and pass it to incident comment."
                                    },
                                    "Terminate_if_there_are_no_inputs_from_sentinel": {
                                        "runAfter": {
                                            "Set_variable_to_error_variable_if_URL_Address_are_not_available_from_sentinel": [
                                                "Succeeded"
                                            ]
                                        },
                                        "type": "Terminate",
                                        "inputs": {
                                            "runError": {
                                                "message": "@variables('Error')"
                                            },
                                            "runStatus": "Failed"
                                        },
                                        "description": "Terminate the playbook if there are no inputs from sentinel"
                                    }
                                }
                            },
                            "expression": {
                                "and": [
                                    {
                                        "greater": [
                                            "@length(body('Entities_-_Get_URLs')?['URLs']?[0]?['Url'])",
                                            0
                                        ]
                                    }
                                ]
                            },
                            "type": "If",
                            "description": "Form this condition, we will check like if body present in the sentinel incident or not and we will check the URL  are available or not."
                        },
                        "Entities_-_Get_URLs": {
                            "runAfter": {},
                            "type": "ApiConnection",
                            "inputs": {
                                "body": "@triggerBody()?['object']?['properties']?['relatedEntities']",
                                "host": {
                                    "connection": {
                                        "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                    }
                                },
                                "method": "post",
                                "path": "/entities/url"
                            }
                        },
                        "Forcepoint_Logo": {
                            "runAfter": {
                                "Initialize_variable_to_Error": [
                                    "Succeeded"
                                ]
                            },
                            "type": "Compose",
                            "inputs": "<img src=\"https://upload.wikimedia.org/wikipedia/en/b/b6/Forcepoint.jpg\" alt=\"ForcepointImage\" width=\"32\" height=\"32\">",
                            "description": "Forcepoint logo for comments "
                        },
                        "Initialize_variable_Terminate": {
                            "runAfter": {
                                "Forcepoint_Logo": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "Terminate",
                                        "type": "string"
                                    }
                                ]
                            },
                            "description": " This holds the variable terminate to terminate the logic app "
                        },
                        "Initialize_variable_append_elements_of_URL_": {
                            "runAfter": {
                                "Initialize_variable_Terminate": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "Elements",
                                        "type": "array"
                                    }
                                ]
                            },
                            "description": "Initialize variable append elements of URL "
                        },
                        "Initialize_variable_for_URL_Address": {
                            "runAfter": {
                                "SMC_API_Key": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "URL Address",
                                        "type": "array"
                                    }
                                ]
                            },
                            "description": "Binding URL to this URL  variable"
                        },
                        "Initialize_variable_to_Error": {
                            "runAfter": {
                                "Initialize_variable_to_SMC_Api_Version_Number": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "Error",
                                        "type": "string"
                                    }
                                ]
                            },
                            "description": "To keep the error into this variable and pass it to wherever required."
                        },
                        "Initialize_variable_to_SMC_Api_Version_Number": {
                            "runAfter": {
                                "Initialize_variable_to_consolidate_variable": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "SMC Api Version Number",
                                        "type": "string",
                                        "value": "[parameters('VersionNumber')]"
                                    }
                                ]
                            },
                            "description": "To keep SMC Api version number. Forcepoint will update the SMC version every year"
                        },
                        "Initialize_variable_to_consolidate_variable": {
                            "runAfter": {
                                "Initialize_variable_to_keep_all_actions": [
                                    "Succeeded"
                                ]
                            },
                            "type": "InitializeVariable",
                            "inputs": {
                                "variables": [
                                    {
                                        "name": "Consolidatevrbl",
                                        "type": "object"
                                    }
                                ]
                            },
                            "description": "To form a JSON object to pass it into Allaction variable"
                        },
                        "Initialize_variable_to_keep_all_actions": {
                            "runAfter": {
                                "Initialize_variable_for_URL_Address": [
                                    "Succeeded"
