{
    "$schema": "https://schema.management.azure.com/schemas/2019-04-01/deploymentTemplate.json#",
    "contentVersion": "1.0.0.0",
    "metadata": {
        "title": "Block or Unblock IP addresses - ForcepointNGFW",
        "description": "This playbook checks if malicious IP address is blocked or unblocked by SMC firewall.",
        "mainSteps": [ "1. Fetches a list of potentially malicious IP addresses", "2. Sends the list of all malicious IP address to SOC via adaptive card.", "3. Soc can block or ignore unblocked IP address as well as unblock or ignore blocked IP address. " ],
        "prerequisites": [
            "1. Forcepoint SMC Custom Connector needs to be deployed prior to the deployment of this playbook under the same resource group.",
            "2. Forcepoint SMC API Key should be known.[Refer here](http://www.websense.com/content/support/library/ngfw/v610/rfrnce/ngfw_6100_ug_smc-api_a_en-us.pdf )",
            "3. Forcepoint SMC Version number should be known. [Refer here](https://help.stonesoft.com/onlinehelp/StoneGate/SMC/)",
            "4. IP address list name for blocking IP address present in SMC should be known",
            "5. Users must have access to Microsoft Teams and they should be a part of a Teams channel and also Power Automate app should be installed in the Microsoft Teams channel."
        ],
        "prerequisitesDeployTemplateFile": "../../ForcepointSMCApiConnector/azuredeploy.json",
        "lastUpdateTime": "2021-07-26T00:00:00.000Z",
        "entities": [ "Ip" ],
        "tags": [ "Teams" ],
        "support": {
            "tier": "community"
        },
        "author": {
            "name": "Accenture"
        }
    },
    "parameters": {
        "PlaybookName": {
            "type": "String",
            "defaultValue": "BlockIP-ResponseOnTeams-ForcepointNGFW",
            "metadata": {
                "description": "Enter name for playbook without spaces. This playbook sends adaptive card for blocking/unblocking IP address."
            }
        },
        "ForcepointSMCConnectorName": {
            "type": "string",
            "defaultValue": "ForcepointSMC-Connector",
            "metadata": {
                "description": "Enter the name for your Forcepoint SMC Connector without spaces"
            }
        },
        "ForcepointSMCApiKey": {
            "type": "securestring",
            "metadata": {
                "description": "Enter the api key for smc login"
            }
        },
        "VersionNumber": {
            "type": "string",
            "defaultValue": "6.8",
            "metadata": {
                "description": "Enter SMC Version Number"
            }
        },
        "IPListName": {
            "type": "string",
            "metadata": {
                "description": "Enter IP List Name present in SMC"
            }
        }
    },
    "variables": {
        "Forcepoint_Connector": "[concat('ForcepointSMCApiConnector-',parameters('PlaybookName'))]",
        "azureSentinel_Connection": "[concat('azuresentienl-',parameters('PlaybookName'))]",
        "teams_connector": "[concat('teamsconnector-',parameters('PlaybookName'))]"
    },
    "resources": [
        {
            "type": "Microsoft.Logic/workflows",
            "apiVersion": "2017-07-01",
            "name": "[parameters('PlaybookName')]",
            "location": "[resourceGroup().location]",
            "dependsOn": [
                "[resourceId('Microsoft.Web/connections', variables('Forcepoint_Connector'))]",
                "[resourceId('Microsoft.Web/connections', variables('azureSentinel_Connection'))]",
                "[resourceId('Microsoft.Web/connections', variables('teams_connector'))]"
            ],
            "identity": {
                "type": "SystemAssigned"
            },
            "properties": {
                "state": "Enabled",
                "definition": {
                    "$schema": "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#",
                    "contentVersion": "1.0.0.0",
                    "parameters": {
                        "$connections": {
                            "defaultValue": {},
                            "type": "Object"
                        }
                    },
                    "triggers": {
                        "Microsoft_Sentinel_incident": {
                            "type": "ApiConnectionWebhook",
                            "inputs": {
                                "body": {
                                    "callback_url": "@{listCallbackUrl()}"
                                },
                                "host": {
                                    "connection": {
                                        "name": "@parameters('$connections')['azuresentinel']['connectionId']"
                                    }
                                },
                                "path": "/incident-creation"
                            }
                        }
                    },
                    "actions": {
                        "Check_if_body_present_from_output": {
                            "actions": {
                                "Check_Login_Status": {
                                    "runAfter": {
                                        "Login": [
                                            "Succeeded",
                                            "Failed",
                                            "Skipped",
                                            "TimedOut"
                                        ]
                                    },
                                    "cases": {
                                        "200_Success_OK": {
                                            "case": 200,
                                            "actions": {
                                                "Condition_to_check_IP_list_exist_or_not": {
                                                    "actions": {
                                                        "Add_IP_Address_into_IP_List": {
                                                            "runAfter": {
                                                                "Condition_based_on_the_SOC_choice_from_adaptive_card": [
                                                                    "Succeeded"
                                                                ]
                                                            },
                                                            "type": "ApiConnection",
                                                            "inputs": {
                                                                "body": {
                                                                    "ip": "@variables('IP Address')"
                                                                },
                                                                "headers": {
                                                                    "Accept": "application/json",
                                                                    "Content-Type": "application/json"
                                                                },
                                                                "host": {
                                                                    "connection": {
                                                                        "name": "@parameters('$connections')['ForcepointSMCApiConnector']['connectionId']"
                                                                    }
                                                                },
                                                                "method": "post",
                                                                "path": "/@{encodeURIComponent(variables('SMC Api Version Number'))}/elements/ip_list/@{encodeURIComponent(last(split(body('Get_IP_List_Element')?['result']?[0]?['href'],'/')))}/ip_address_list"
                                                            }
                                                        },
                                                        "Bind_Column_set_string": {
                                                            "runAfter": {
                                                                "Set_variable_to_column_set_string": [
                                                                    "Succeeded"
                                                                ]
                                                            },
                                                            "type": "Compose",
                                                            "inputs": "@variables('Column set string')"
                                                        },
                                                        "Condition_based_on_the_SOC_choice_from_adaptive_card": {
                                                            "actions": {
                                                                "Bind_SOC_response_string": {
                                                                    "runAfter": {
                                                                        "Set_variable_to_column_set_string_after_SOC_response": [
                                                                            "Succeeded"
                                                                        ]
                                                                    },
                                                                    "type": "Compose",
                                                                    "inputs": "@variables('Column set string')",
                                                                    "description": "Bind SOC response string"
                                                                },
                                                                "For_each_IP_Address": {
                                                                    "foreach": "@body('Entities_-_Get_IPs')?['IPs']",
                                                                    "actions": {
                                                                        "Binding_IP_Address": {
                                                                            "runAfter": {},
                                                                            "type": "Compose",
                                                                            "inputs": "@items('For_each_IP_Address')?['Address']"
                                                                        },
                                                                        "Soc_Action": {
                                                                            "runAfter": {
                                                                                "Binding_IP_Address": [
                                                                                    "Succeeded"
                                                                                ]
                                                                            },
                                                                            "type": "Compose",
                                                                            "inputs": "@body('Post_an_Adaptive_Card_to_a_Teams_channel_and_wait_for_a_response')?['data']?[outputs('Binding_IP_Address')]",
                                                                            "description": " This action will bind SOC action  "
                                                                        },
                                                                        "Switch_case_to_check_SOC_action_output_on_each_IP_address": {
                                                                            "runAfter": {
                                                                                "Soc_Action": [
                                                                                    "Succeeded"
                                                                                ]
                                                                            },
                                                                            "cases": {
                                                                                "Block": {
                                                                                    "case": "Block",
                                                                                    "actions": {
                                                                                        "Append_to_IP_address_to_IP_list": {
                                                                                            "runAfter": {},
                                                                                            "type": "AppendToArrayVariable",
                                                                                            "inputs": {
                                                                                                "name": "IP Address",
                                                                                                "value": "@items('For_each_IP_Address')?['Address']"
                                                                                            },
                                                                                            "description": "Append to IP address to IP list"
                                                                                        },
                                                                                        "Append_to_array_variable_to_all_actions_array": {
                                                                                            "runAfter": {
                                                                                                "Set_variable_to_Consolidate_variable_from_response_SOC": [
                                                                                                    "Succeeded"
                                                                                                ]
                                                                                            },
                                                                                            "type": "AppendToArrayVariable",
                                                                                            "inputs": {
                                                                                                "name": "Arrayforallactions",
                                                                                                "value": "@variables('Consolidatevrbl')"
                                                                                            }
                                                                                        },
                                                                                        "Append_to_array_variable_to_column_set_array_after_soc_response": {
                                                                                            "runAfter": {
                                                                                                "Set_variable_to_column_set_from_soc_response": [
                                                                                                    "Succeeded"
                                                                                                ]
                                                                                            },
                                                                                            "type": "AppendToArrayVariable",
                                                                                            "inputs": {
                                                                                                "name": "Column set array",
                                                                                                "value": "@variables('Create Column Set')"
                                                                                            },
                                                                                            "description": "Append to array variable to column set array after soc response"
                                                                                        },
                                                                                        "Set_variable_to_Consolidate_variable_from_response_SOC": {
                                                                                            "runAfter": {
                                                                                                "Append_to_IP_address_to_IP_list": [
                                                                                                    "Succeeded"
                                                                                                ]
                                                                                            },
                                                                                            "type": "SetVariable",
                                                                                            "inputs": {
                                                                                                "name": "Consolidatevrbl",
                                                                                                "value": {
                                                                                                    "Action": "Blocked by SOC",
                                                                                                    "IPAddres": "@{items('For_each_IP_Address')?['Address']}",
                                                                                                    "IPStatus": "Blocked",
                                                                                                    "IncidentSeverity": "@{triggerBody()?['object']?['properties']?['severity']}"
                                                                                                }
                                                                                            },
                                                                                            "description": "Set variable to Consolidate variable from response SOC"
                                                                                        },
                                                                                        "Set_variable_to_column_set_from_soc_response": {
                                                                                            "runAfter": {
                                                                                                "Append_to_array_variable_to_all_actions_array": [
                                                                                                    "Succeeded"
                                                                                                ]
                                                                                            },
                                                                                            "type": "SetVariable",
                                                                                            "inputs": {
                                                                                                "name": "Create Column Set",
                                                                                                "value": {
                                                                                                    "columns": [
                                                                                                        {
                                                                                                            "bleed": true,
                                                                                                            "items": [
                                                                                                                {
                                                                                                                    "text": "@{items('For_each_IP_Address')?['Address']}",
                                                                                                                    "type": "TextBlock",
                                                                                                                    "wrap": true
                                                                                                                }
                                                                                                            ],
                                                                                                            "type": "Column",
                                                                                                            "width": "stretch"
                                                                                                        },
                                                                                                        {
                                                                                                            "bleed": true,
                                                                                                            "items": [
                                                                                                                {
                                                                                                                    "text": "Blocked",
                                                                                                                    "type": "TextBlock"
                                                                                                                }
                                                                                                            ],
                                                                                                            "type": "Column",
                                                                                                            "width": "stretch"
                                                                                                        }
                                                                                                    ],
                                                                                                    "style": "emphasis",
                                                                                                    "type": "ColumnSet"
                                                                                                }
                                                                                            },
                                                                                            "description": "Set variable to column set from soc response"
                                                                                        }
                                                                                    }
                                                                                },
                                                                                "Unblock": {
                                                                                    "case": "Unblock",
                                                                                    "actions": {
                                                                                        "Append_to_array_variable_to_all_action_array_If_soc_is_unblocked_IP": {
                                                                                            "runAfter": {
                                                                                                "Set_variable_for_consolidate_variable_if_soc_unblocked_IP": [
                                                                                                    "Succeeded"
                                                                                                ]
                                                                                            },
                                                                                            "type": "AppendToArrayVariable",
                                                                                            "inputs": {
                                                                                                "name": "Arrayforallactions",
                                                                                                "value": "@variables('Consolidatevrbl')"
                                                                                            },
                                                                                            "description": "Append to array variable to all action array If soc is unblocked IP"
                                                                                        },
                                                                                        "Append_to_array_variable_to_column_set_array_if_SOC_unblocked_IP": {
                                                                                            "runAfter": {
                                                                                                "Set_variable_to_column_set_if_IP_is_unblocked_by_SOC": [
                                                                                                    "Succeeded"
                                                                                                ]
                                                                                            },
                                                                                            "type": "AppendToArrayVariable",
                                                                                            "inputs": {
                                                                                                "name": "Column set array",
                                                                                                "value": "@variables('Create Column Set')"
                                                                                            },
                                                                                            "description": "Append to array variable to column set array if SOC unblocked IP"
                                                                                        },
                                                                                        "Filter_array": {
                                                                                            "runAfter": {},
                                                                                            "type": "Query",
                                                                                            "inputs": {
                                                                                                "from": "@variables('IP Address')",
                                                                                                "where": "@not(equals(item(), items('For_each_IP_Address')?['Address']))"
                                                                                            }
                                                                                        },
                                                                                        "Set_variable_for_IP_address_list": {
                                                                                            "runAfter": {
                                                                                                "Filter_array": [
                                                                                                    "Succeeded"
                                                                                                ]
                                                                                            },
                                                                                            "type": "SetVariable",
                                                                                            "inputs": {
                                                                                                "name": "IP Address",
                                                                                                "value": "@body('Filter_array')"
                                                                                            },
                                                                                            "description": "After removing IP address from IP address list and bind the list again to IP address list"
                                                                                        },
                                                                                        "Set_variable_for_consolidate_variable_if_soc_unblocked_IP": {
                                                                                            "runAfter": {
                                                                                                "Set_variable_for_IP_address_list": [
                                                                                                    "Succeeded"
                                                                                                ]
                                                                                            },
                                                                                            "type": "SetVariable",
                                                                                            "inputs": {
                                                                                                "name": "Consolidatevrbl",
                                                                                                "value": {
                                                                                                    "Action": "Unblocked by SOC",
                                                                                                    "IPAddres": "@{items('For_each_IP_Address')?['Address']}",
                                                                                                    "IPStatus": "Unblocked",
                                                                                                    "IncidentSeverity": "@{triggerBody()?['object']?['properties']?['severity']}"
                                                                                                }
                                                                                            },
                                                                                            "description": "Set variable for consolidate variable if soc unblocked IP"
                                                                                        },
                                                                                        "Set_variable_to_column_set_if_IP_is_unblocked_by_SOC": {
                                                                                            "runAfter": {
                                                                                                "Append_to_array_variable_to_all_action_array_If_soc_is_unblocked_IP": [
                                                                                                    "Succeeded"
                                                                                                ]
                                                                                            },
                                                                                            "type": "SetVariable",
                                                                                            "inputs": {
                                                                                                "name": "Create Column Set",
                                                                                                "value": {
                                                                                                    "columns": [
                                                                                                        {
                                                                                                            "bleed": true,
                                                                                                            "items": [
                                                                                                                {
                                                                                                                    "text": "@{items('For_each_IP_Address')?['Address']}",
                                                                                                                    "type": "TextBlock",
                                                                                                                    "wrap": true
                                                                                                                }
                                                                                                            ],
                                                                                                            "type": "Column",
                                                                                                            "width": "stretch"
                                                                                                        },
                                                                                                        {
                                                                                                            "bleed": true,
                                                                                                            "items": [
                                                                                                                {
                                                                                                                    "text": "Unblocked",
                                                                                                                    "type": "TextBlock"
                                                                                                                }
                                                                                                            ],
                                                                                                            "type": "Column",
                                                                                                            "width": "stretch"
                                                                                                        }
                                                                                                    ],
                                                                                                    "style": "emphasis",
                                                                                                    "type": "ColumnSet"
                                                                                                }
                                                                                            },
                                                                                            "description": "Set variable to column set if IP is unblocked by SOC"
                                                                                        }
                                                                                    }
                                                                                }
                                                                            },
                                                                            "default": {
                                                                                "actions": {
                                                                                    "Condition_to_check_IP_address_status_if_SOC_is_ignored": {
                                                                                        "actions": {
                                                                                            "Append_to_array_variable_to_all_action_array_if__Ip_is_ignored": {
                                                                                                "runAfter": {
                                                                                                    "Set_variable_to_consolidate_variable_if_IP_skipped_by_soc": [
                                                                                                        "Succeeded"
                                                                                                    ]
                                                                                                },
                                                                                                "type": "AppendToArrayVariable",
                                                                                                "inputs": {
                                                                                                    "name": "Arrayforallactions",
                                                                                                    "value": "@variables('Consolidatevrbl')"
                                                                                                },
                                                                                                "description": "Append to array variable to all action array if  Ip is ignored"
                                                                                            },
                                                                                            "Append_to_array_variable_to_column_set_array_if_IP_is_ignored_by_SOC": {
                                                                                                "runAfter": {
                                                                                                    "Set_variable_to_column_set_if_IP_is_ignored_by_SOC": [
                                                                                                        "Succeeded"
                                                                                                    ]
                                                                                                },
                                                                                                "type": "AppendToArrayVariable",
                                                                                                "inputs": {
                                                                                                    "name": "Column set array",
                                                                                                    "value": "@variables('Create Column Set')"
                                                                                                },
