    "contentVersion": "1.0.0.0",
    "metadata":{
        "comments": "This playbook will open a new request in ManageEngine Service Desk Plus On Demand",
        "author": "Robert Kitching"
    },
    "parameters": {
        "PlaybookName": {
            "defaultValue": "Open-ServiceDeskPlusOnDemand-Ticket",
            "type": "string"
